main_review.command:
$ErrorActionPreference='Stop'
foreach ($mode in @('--verify-public','--verify-licensed')) {
 $verificationText = uv run --offline --frozen --no-sync python -B artifacts/rp4_cleanup_review/inventory_review.py $mode
 if ($LASTEXITCODE -ne 0) { throw "VERIFICATION_FAILED:$mode" }
 $verified = $verificationText | ConvertFrom-Json
 $verified | Select-Object status,mode,checked_files,private_hash_checks_skipped,failures,model_fits,inference_runs | ConvertTo-Json -Compress
}
uv run --offline --frozen --no-sync python -B -m pytest -q -p no:cacheprovider artifacts/rp4_cleanup_review/test_inventory_review.py
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
uv run --offline --frozen --no-sync ruff check artifacts/rp4_cleanup_review/inventory_review.py artifacts/rp4_cleanup_review/test_inventory_review.py
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
uv run --offline --frozen --no-sync ruff format --check artifacts/rp4_cleanup_review/inventory_review.py artifacts/rp4_cleanup_review/test_inventory_review.py
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
uv run --offline --frozen --no-sync mypy --explicit-package-bases --follow-imports=silent artifacts/rp4_cleanup_review/inventory_review.py artifacts/rp4_cleanup_review/test_inventory_review.py

